def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = []
    weak_prev = []
    desperate_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 85:
                    strong_prev.append(bid)
                else:
                    weak_prev.append(bid)

    if not alive:
        return max(0.0, min(budget, 18.0))

    contested = supply < (len(alive) + 1) * WATER_REQ

    highest_prev = max(prev_bids) if prev_bids else 0.0
    low_prev = min(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if day >= 8:
        urgency += 1

    if contested:
        urgency += 1

    if urgency <= 1:
        bid = 8.0 if contested else 15.0
        if desperate_count >= 2:
            bid = 5.0
    elif urgency == 2:
        if strong_prev:
            bid = min(52.0, avg_prev * 0.55)
        else:
            bid = max(28.0, low_prev + 2.0)
    elif urgency == 3:
        if strong_prev:
            bid = max(58.0, min(78.0, highest_prev * 0.72))
        else:
            bid = max(45.0, highest_prev + 3.0)
    elif urgency == 4:
        if strong_prev:
            bid = max(72.0, min(96.0, highest_prev + 1.5))
        else:
            bid = max(62.0, highest_prev + 4.0)
    else:
        if strong_prev:
            bid = max(88.0, min(110.0, highest_prev + 3.0))
        else:
            bid = max(78.0, highest_prev + 6.0)

    if budget < bid:
        bid = budget

    if budget <= 35:
        bid = min(budget, max(bid, budget * 0.9 if urgency >= 4 else budget * 0.5))

    if hp >= 8 and no_water == 0 and strong_prev and highest_prev >= 100 and contested:
        bid = min(budget, min(bid, 12.0))

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    # If no one else is alive, bid conservatively
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids only (immediate reaction)
    yesterday_bids = []
    yesterday_hp_after = []
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
                yesterday_hp_after.append(float(prev.get('hp_after', 0)))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Supply pressure: higher supply reduces need to overbid
    # Map supply in [15,25] to a factor in [1.1, 0.8]
    if MAX_SUPPLY - MIN_SUPPLY != 0:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    supply_factor = 1.1 - 0.3 * t

    # If I'm in danger, bid aggressively to avoid no-water days
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Estimate how many water units we can reasonably cover if we win/lose.
    # Use hp and no_water_days to decide urgency.
    urgency = 0
    if hp <= 2.0:
        urgency += 2
    if hp <= 5.0:
        urgency += 1
    if no_water_days >= 2:
        urgency += 2
    if no_water_days >= 1:
        urgency += 1

    # Decide target bid based on yesterday's observed pressure.
    # Alex/Eric were bidding very high and survived; Cindy died early (likely underbid).
    # So: if yesterday highest bid was very high, don't go too low; but avoid maxing out.
    if highest_prev_bid >= DAILY_SALARY * 1.15:
        base = DAILY_SALARY * 0.62
        if urgency >= 3:
            base = DAILY_SALARY * 0.85
        elif urgency == 2:
            base = DAILY_SALARY * 0.75
        else:
            base = DAILY_SALARY * 0.68
    else:
        # Lower overall pressure; bid enough to beat weaker bidders
        base = max(DAILY_SALARY * 0.48, avg_prev_bid * 0.9)
        if urgency >= 3:
            base = DAILY_SALARY * 0.8
        elif urgency == 2:
            base = DAILY_SALARY * 0.7

    # Scale by supply factor
    target = base * supply_factor

    # Ensure we don't overspend: keep some runway for later days.
    # If budget is low, cap by 95% of budget.
    cap = budget * 0.95
    target = min(target, cap)

    # If budget is extremely low, still bid something small to try to avoid death spiral
    if budget <= 1.0:
        return 0.0

    # Final clamp
    if target < 0.0:
        target = 0.0
    return float(target)

